window.DGNL_DE_MON["l9"] = {"id": "l9", "ten": "Đề thi thử số 9", "tv": [{"noiDungChung": null, "cauHoi": [{"question": "Xác định phương án chứa từ <b>sai</b> chính tả.", "choices": ["viển vông", "căn vặn", "xơ xài", "giảng hoà"], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "“Đồng chí Bình An tuy đã kiệt sức nhưng anh vẫn rất cố gắng để hoàn thành nhiệm vụ chuyển thương.”<br>Hai vế của câu ghép trên có mối quan hệ gì?", "choices": ["tương phản – nhượng bộ", "điều kiện – kết quả", "nguyên nhân – kết quả", "mục đích – sự kiện"], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn từ phương án chứa từ “mắt” mang nghĩa khác với những phương án khác.", "choices": ["“Mắt kia em có sầu cô quạnh/Khi chớm heo về một sớm mai?” (Đôi bờ, Quang Dũng)", "“Mắt em là một dòng sông/Thuyền anh bơi lội trong dòng mắt em” (Đôi mắt, Lưu Trọng Lư)", "“Phải chăng tôi đã yêu rồi/ Hồn xin quỳ dưới mắt người từ đây”. (Mắt Nhung, Nguyễn Bính)", "“Đêm cuối mùa trăng rơi mặt sông vắng/ Mắt trời thu rơm rớm những giọt sao” (Soi mình lên nước mắt, Trần Văn Thiên)"], "correctIndex": 3, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn phương án chứa cụm từ <b>không</b> cùng kết cấu với các phương án còn lại.", "choices": ["đóng cửa cài then", "máu chảy ruột mềm", "vật đổi sao dời", "phượng chạ loan chung"], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn câu không mắc lỗi dùng từ", "choices": ["Tôi nghe phong phanh chuyện cô ta sắp kết hôn với người bạn cũ.", "Với nụ cười thường trực trên môi, An mang lại cho căn phòng một bầu khí quyển tích cực.", "Đọc lướt qua các tít báo, chị dừng lại ở một dòng tin nhỏ.", "Do tính cách lanh lợi, cậu ta hay nói năng thiếu suy nghĩ."], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Những bản đánh giá về chất lượng công việc của công nhân cho thấy năng suất lao động đã được cải thiện rõ rệt. </i><br>Đây là câu ____.<br>Điền vào chỗ trống:", "choices": ["mơ hồ cấu trúc", "mơ hồ từ vựng", "sai ngữ pháp", "đúng"], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Vì nhịn đói cả ngày, vừa mở hộp cơm, đứa bé xúc từng muỗng, nhai ngấu nghiến và ngồi xuống bàn.<br>Câu trên mắc lỗi gì?", "choices": ["Sai quy chiếu", "Sai logic", "Mơ hồ từ vựng", "Lỗi dấu câu"], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "“Qua việc phân tích các hiện tượng xã hội đã cho thấy rằng giới trẻ ngày nay đang dần thay đổi cách nhìn về giá trị sống.”<br>Câu trên mắc lỗi ngữ pháp. Chọn phương án sửa phù hợp nhất:", "choices": ["Phân tích các hiện tượng xã hội đã cho thấy rằng giới trẻ ngày nay đang dần thay đổi cách nhìn về giá trị sống.", "Việc phân tích các hiện tượng xã hội đã cho thấy rằng giới trẻ ngày nay đang dần thay đổi cách nhìn về giá trị sống.", "Giới trẻ ngày nay, qua việc phân tích các hiện tượng xã hội, đang dần thay đổi cách nhìn về giá trị sống.", "Qua việc phân tích các hiện tượng xã hội, giới trẻ ngày nay cho thấy rằng họ đang dần thay đổi cách nhìn về giá trị sống."], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Nếu xem quyền lực và tiền bạc là </i><b><i>cứu cánh</i></b><i>, con người rất dễ rơi vào trạng thái tha hóa và đánh mất chính mình.</i><br>Từ “cứu cánh” được hiểu đúng nhất là gì?", "choices": ["mục đích tối thượng", "điểm tựa tinh thần", "giải pháp", "lẽ sống"], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn từ “chỉ” khác loại với các từ còn lại", "choices": ["Vết thương đã cắt chỉ.", "Chỉ tay chằng chịt.", "Uống thuốc đúng chỉ dẫn của bác sĩ.", "Chỉ biết lo cho bản thân mình thôi."], "correctIndex": 3, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Tôi đã đến nhiều đất nước ở các châu lục, đã được thấy hoa Lau ở đâu đó trên những sườn đồi, chân núi, bãi sông hay bên những nẻo đường, những vạt rừng nhiệt đới. Ở Thủ đô một vương quốc phía bắc châu Phi, bên bờ Địa Trung Hải, hoa Lau còn được trồng trong những bồn hoa ở những công viên hay hai bên đường phố, được chăm chút để cả vạt hoa Lau nở ra trắng muốt, xốp nhẹ, bồng bềnh như sương khói mỗi khi có làn gió nhẹ thổi qua, đẹp đến thơ mộng. Nhưng chẳng ở đâu, hoa Lau có hồn vía như ở đất nước ta. </i>(Hồn lau, Ngọc Tấn)<br>Đâu là biện pháp tu từ không có trong đoạn trích trên?", "choices": ["Điệp cấu trúc", "So sánh", "Liệt kê", "Chêm xen"], "correctIndex": 3, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Thuở hỗn mang chưa có gì được tạo lập chỉ mới có hai đấng cùng thành hình một lượt là Nhiêu Vương (tức Ngọc Hoàng) và Bàn Cồ. Nhiêu Vương có ba trăm sáu con mắt, Bàn Cồ có ba trăm sáu thân hình. Con mắt bên trái của Nhiêu Vương sinh ra mặt trời (dương), con mắt bên phải sinh ra mặt trăng (âm), đầu làm thành trời, chân làm thành đất. Còn loài người thì do tâm của Bàn Cồ mà sinh ra, trong đó có Bàn Vũ. Bàn Vũ đã giúp vua Trung Hoa dẹp giặc bằng cách hóa thành một con chó đi vào thành giặc, thừa lúc vua giặc đang say rượu, nằm ngủ, nhảy lại cắn chết, rồi chặt đầu mang về. Bàn Vũ được vua Trung Hoa trọng thưởng, cắt đất và gả công chúa thứ ba cho như đã hứa. Bàn Vũ và công chúa sinh ra được sáu trai và sáu gái thành tổ tiên người Mán. Hai vợ chồng Bàn Vũ về ở núi Cối-kê cai quản giang sơn, núi rừng của nhà vua đã cắt cho.</i><br><i>Đến ngày nay người Mán vẫn nhớ mình là con cháu của Cẩu Long (chó rồng), kiêng ăn thịt vật tổ, quần áo phụ nữ thêu dệt các hình ảnh nhắc nhở đến vật tổ, và trong vài bộ lạc Mán, đàn ông còn giữ tục lệ mang tóc kết như đuôi chó để nhớ đến nguồn gốc của bộ tộc.</i><br>(Thần thoại Việt Nam - Trung Hoa, Doãn Quốc Sỹ sưu tập và dịch thuật, NXB Sáng tạo, 1970)<br>Đâu là nhận định KHÔNG đúng về đoạn trích?", "choices": ["Đoạn trích thể hiện đặc trưng của thần thoại suy nguyên khi lí giải sự hình thành vũ trụ, con người và một tộc người cụ thể.", "Hình tượng Bàn Vũ mang dấu ấn của tư duy vật tổ, phản ánh mối quan hệ huyết thống giữa con người với loài vật linh thiêng.", "Đoạn trích cho thấy sự giao thoa giữa thần thoại và truyền thuyết khi manh nha xuất hiện yếu tố lịch sử.", "Vua Trung Hoa là kết tinh của phẩm chất cộng đồng nên được Bàn Vũ giúp đỡ để chinh phạt quân thù, mở rộng lãnh thổ."], "correctIndex": 3, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Đế Thích: Ông Trương Ba... (đắn đo rất lâu rồi quyết định) Vì lòng quí mến ông, tôi sẽ làm cu Tị sống lại, dù có bị phạt nặng... Nhưng còn ông... rốt cuộc ông muốn nhập vào thân thể ai?</i><br><i>Hồn Trương Ba: (sau một hồi lâu): Tôi đã nghĩ kĩ... (nói chậm và khẽ) Tôi không nhập vào hình thù ai nữa! Tôi đã chết rồi, hãy để tôi chết hắn!</i><br><i>Đế Thích: Không thể được! Việc ông phải chết chỉ là một lầm lẫn của quan thiên đình. Cái sai ấy đã được sửa bằng cách làm cho hồn ông được sống.</i><br><i>Hồn Trương Ba: Có những cái sai không thể sửa được. Chắp vá gượng ép chỉ càng làm sai thêm. Chỉ có cách là đừng bao giờ sai nữa, hoặc phải bù lại bằng một việc đúng khác. Việc đúng còn làm kịp bây giờ là làm cu Tị sống lại. Còn tôi, cứ để tôi chết hắn...</i><br><i>(Lưu Quang Vũ, Hồn Trương Ba, da hàng thịt, Ngữ văn 12, tập hai, NXB Giáo dục – 2008, tr 151-152)</i><br>Đâu là nhận xét đúng nhất về nhân vật Hồn Trương Ba trong đoạn trích?", "choices": ["Hồn Trương Ba là người có ý thức sâu sắc về nhân cách, kiên quyết từ chối kiểu sống chắp vá.", "Hồn Trương Ba là người giàu lòng vị tha, sẵn sàng hi sinh sự sống của mình để mang lại hạnh phúc cho người khác.", "Hồn Trương Ba là người tỉnh táo nhận ra những sai lầm của hoàn cảnh, từ đó lựa chọn cách ứng xử nhằm khắc phục hậu quả.", "Hồn Trương Ba là người đề cao đời sống tinh thần, sẵn sàng từ bỏ thể xác để giữ gìn sự trong sạch của tâm hồn."], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>[...] Trước đây, anh cứ nghĩ không biết đến bao giờ dân tộc Việt Nam mới ra khỏi vòng trói buộc. Phan Đình Phùng, Hoàng Hoa Thám, Phan Bội Châu, Nguyễn Thái Học nối tiếp nhau thất bại. Anh có ngờ đâu Cách mạng Tháng Tám nổ ra, nước Việt Nam nhỏ bé của anh ngang nhiên thành lập chế độ cộng hoà dân chủ đầu tiên ở châu Á, và chính anh lại được sống những ngày lớn lao ấy. Anh bàng hoàng như mê như say, mặt bừng bừng nóng. Anh nhảy nhót trên đường đầy ánh sáng của một mùa thu tuyệt đẹp. Anh ngẩng đầu ngắm lá cờ đỏ sao vàng trên đỉnh cột cờ, nhìn vòm trời xanh lồng lộng. Cây cối hai bên đường reo vui. Chung quanh toàn là đồng bào của anh. Không còn bóng một thằng Pháp ngạo nghễ, hống hách. Anh yêu tất cả mọi người, và anh nói rất nhiều. Anh đi suốt từ Ba Đình về Nhà Hát Lớn, rồi lại từ Nhà Hát Lớn trở về Ba Đình. Anh ngẩng đầu đến mỏi cổ, chân anh bước đến long gối. Nhưng anh cứ đi và mãi không muốn trở về. Tất cả người Hà Nội đều đổ ra đường. Người không quen nhau cũng gật đầu chào hỏi. Tiệc mở linh đình ở hầu hết các nhà mà cánh cửa mở toang. Người ta như bừng tỉnh một giấc ngủ triền miên. Vui đẹp lạ lùng, là những con đường sạch bóng quân thống trị dưới bầu trời Tổ quốc trong lành. </i><br>(Trích Sống mãi với thủ đô, Nguyễn Huy Tưởng)<br>Nhận xét nào <b>đúng nhất</b> về sự chuyển biến trong tâm lí của nhân vật “anh” trong đoạn trích?", "choices": ["Từ sự hoài nghi về năng lực lãnh đạo của các bậc tiền bối sang niềm tin tuyệt đối vào sức mạnh của tầng lớp trí thức tiểu tư sản.", "Từ trạng thái bi quan, bế tắc trước vận mệnh dân tộc sang niềm vui sướng, ngỡ ngàng và say mê trước thắng lợi của Cách mạng Tháng Tám.", "Từ thái độ thờ ơ, lãnh đạm với thời cuộc sang sự hối hận và quyết tâm tham gia vào các phong trào cứu nước của nhân dân Thủ đô.", "Từ nỗi sợ hãi trước sự bạo ngược của quân xâm lược sang cảm giác tự hào, hãnh diện khi thấy vị thế của Việt Nam trên trường quốc tế."], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><i>Hoa giãi nguyệt, nguyệt in một tấm</i><br><i>Nguyệt lồng hoa, hoa thắm từng bông</i><br><i>Nguyệt hoa, hoa nguyệt trùng trùng</i><br><i>Trước hoa, dưới nguyệt, trong lòng xiết đau</i><br>(Trích Chinh phụ ngâm, Đặng Trần Côn, Phan Huy Ích dịch)<br>Qua sự đối lập giữa tình cảnh của người chinh phụ và hình ảnh thiên nhiên “hoa” – “nguyện”, tình cảm nào được hiện lên rõ nét nhất?", "choices": ["Nỗi buồn tủi, cô đơn trước sự tàn phai của tuổi tác khi nhìn thiên nhiên.", "Nỗi cô đơn và khát khao giao hoà lứa đôi.", "Nỗi oán hận trước chiến tranh chi cắt đôi lứa/", "Sự cơ cực, vất vả của người vợ có chồng ra trận, không được chở che."], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><i>Nhớ lời nguyện ước ba sinh,</i><br><i>Xa xôi ai có biết tình chăng ai?</i><br><i>Khi về hỏi liễu Chương Đài,</i><br><i>Cành xuân đã bẻ cho người chuyên tay?</i><br>(Truyện Kiều, Nguyễn Du)<br>“Liễu Chương Đài” và “cành xuân” trong đoạn thơ trên tượng trưng cho điều gì?", "choices": ["Người con gái đẹp và tình yêu trong sáng, chung thủy.", "Kim Trọng và tình yêu, tuổi trẻ của Thuý Kiều.", "Thuý Kiều và tình yêu, tuổi trẻ của Thuý Kiều.", "Người con gái đẹp và tuổi trẻ, sắc đẹp."], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><i>Khi cơn say của cha thành bão xoáy qua nhà</i><br><i>Mẹ chân trần lên đồi cỏ khô</i><br><i>Và khóc</i><br><i>Những hàng dương liễu cúi đầu lặng im</i><br><i>Mẹ úp mặt vào trăng</i><br><i>Những giọt trăng giàn giụa khoé mắt</i><br><i>Trăng chảy thành sông trôi đi biền biệt</i><br><i>Ai khất thực những lời ru, trong từng đêm gió trở</i><br><i>Để lại bóng mình phía những phiến sương loang</i><br>(Tìm lên ngọn đồi nức nở vần trăng, Trần Văn Thiên)<br>Nhận xét nào <b>đúng nhất</b> về mối quan hệ giữa hình ảnh người mẹ và không gian xung quanh?", "choices": ["Người mẹ đối lập với thiên nhiên tĩnh lặng.", "Người mẹ dần hòa vào thiên nhiên, nỗi đau lan tỏa sang cảnh vật.", "Người mẹ tách biệt khỏi thiên nhiên, tồn tại trong cô đơn tuyệt đối.", "Thiên nhiên là phông nền cho hành động của người mẹ."], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>“Có răng nói thật đi nha</i><br><i>Lúc trăng đang tỏ thì hoa đang thì.”</i><br>Câu ca dao trên chơi chữ dựa trên hiện tượng gì?", "choices": ["Đồng âm", "Nói lái", "Điệp âm", "Trại âm"], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Có thể nói, thế kỉ XV–XVII chủ yếu là thế kỉ của ________. Với đặc điểm dùng hình thức kì ảo làm phương thức chuyển tải nội dung, tác phẩm thuộc thể loại này có sức hấp dẫn mạnh mẽ mọi lứa tuổi, mọi thời đại. Người đọc được cùng các nhân vật phiêu diêu vào thế giới ảo huyền ở cả bốn cõi không gian vừa phi quảng tính, vừa vô định hướng và hành trình trong thời gian phi tuyến tính với độ đàn hồi ảo hoá có thể “co” tám thập kỉ vào một năm hoặc, đang từ hiện tại “nhảy” về quá khứ của kiếp trước và “bước” sang tương lai của kiếp sau.<br>(Trích theo Nguyễn Đăng Na)<br>Điền từ vào chỗ trống:", "choices": ["Truyện lịch sử", "Truyện truyền kì", "Truyện viễn tưởng", "Truyền thuyết"], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Hai bộ phận chủ yếu của văn học Việt Nam từ đầu thế kỉ XX đến Cách mạng tháng Tám năm 1945 là hai bộ phận nào?", "choices": ["Văn học chữ Hán và văn học chữ Nôm", "Văn học lãng mạn và văn học hiện thực", "Văn học công khai và văn học không công khai", "Văn học bình dân và văn học cung đình"], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": "<i>“Những ngày cuối của dòng Mekong hùng vĩ” cảnh báo các quốc gia có thể &quot;giết chết&quot; dòng sông với chính sách kinh tế không phù hợp. Quyển sách khái quát mối quan hệ giữa Trung Quốc - nơi dòng sông Mekong bắt đầu - và các nước Đông Nam Á. Mekong đang đối mặt với các vấn đề: ô nhiễm do rác thải, du lịch, công nghiệp hóa và cạn kiệt nguồn nước do dự án thủy điện.</i><br><i>Sách &quot;Những ngày cuối của dòng Mekong hùng vĩ&quot;, xuất bản lần đầu năm 2017.</i><br><i>Mekong là nền tảng của một hệ sinh thái từ sông băng, hồ, đồng bằng, đến từng kênh, rạch nhỏ. Sự đa dạng sinh học của sông có ý nghĩa toàn cầu - khi sản lượng cá đánh bắt được gấp 13 lần so với số lượng ở sông, hồ Bắc Mỹ</i><br><i>Eyler phân tích những dự án phát triển kinh tế không đề cao những lợi ích bền vững, tác động xấu đến hệ sinh thái. Như tại Campuchia, người dân đánh bắt cá &quot;quá tay&quot;, tiêu diệt triệt để nguồn cá và làm nguy hại đến sinh cảnh. Lào dự tính xây đập nước thứ sáu, do muốn trở thành trung tâm sản xuất thủy điện, bán cho nước khác. Theo tác giả, Trung Quốc chịu trách nhiệm lớn cho sự thoái hóa của Mekong. Đập thủy điện ở sông Lan Thương (Trung Quốc), thường xuyên giữ lại nước ở thượng nguồn, khiến những quốc gia như Lào, Thái Lan... hạn hán.</i><br><i>[...] Eyler trăn trở sự đa dạng sinh học - điều làm Mekong hùng vĩ sẽ biến mất. Ông muốn ghi lại tư liệu về dòng sông qua tiếp xúc với người bản địa. Eyler quan sát thiên nhiên, con người vùng Mekong thay đổi trong nhiều năm liền. Văn hóa địa phương dần mất đi, người trẻ không còn mặn mà với các công việc ở nông thôn. Điều này thúc đẩy công nghiệp hóa ở các nước đang phát triển - vốn không nghiêm ngặt trong quy chế xử lý rác thải đô thị, khiến dòng Mekong ô nhiễm.</i><br>(Trích theo Sách cảnh báo về thực trạng Đồng Mekong. Quỳnh Quyên VnExpress.)", "cauHoi": [{"question": "Thông tin chính của văn bản trên là gì?", "choices": ["Vai trò kinh tế của sông Mekong đối với các quốc gia Đông Nam Á.", "Thực trạng suy thoái của sông Mekong và những nguyên nhân.", "Giới thiệu cuốn sách “Những ngày cuối của dòng Mekong hùng vĩ”.", "Quá trình hình thành và phát triển của hệ sinh thái sông Mekong."], "correctIndex": 1, "explain": ""}, {"question": "Thông tin trong đoạn “Eyler phân tích những dự án phát triển kinh tế... hạn hán” được trình bày chủ yếu theo cấu trúc nào?", "choices": ["Nguyên nhân – kết quả.", "So sánh đối chiếu", "Thông tin chính – thông tin chi tiết", "Trật tự thời gian"], "correctIndex": 2, "explain": ""}, {"question": "Theo văn bản, đâu không phải là nguyên nhân khiến sông Mekong suy thoái?", "choices": ["Ô nhiễm từ rác thải và công nghiệp hóa.", "Phát triển du lịch thiếu kiểm soát.", "Biến đổi khí hậu toàn cầu làm tan băng.", "Xây dựng các đập thủy điện và khai thác quá mức nguồn cá."], "correctIndex": 2, "explain": ""}, {"question": "Tác dụng của hình ảnh trong văn bản là gì?", "choices": ["Làm bằng chứng khách quan cho những tác hại được trình bày.", "Minh hoạ cho nhận định ngôn ngữ được trình bày trước đó.", "Giúp người đọc hiểu về hình ảnh và đặc điểm sông Mekong", "Bổ sung thông tin về năm xuất bản của cuốn sách."], "correctIndex": 1, "explain": ""}, {"question": "Ý nghĩa nào sau đây không thể rút ra từ văn bản?", "choices": ["Phát triển kinh tế thiếu bền vững gây tổn hại nghiêm trọng đến hệ sinh thái.", "Các quốc gia trong khu vực đều có trách nhiệm nhất định đối với sự suy thoái của Mekong.", "Sự thay đổi văn hóa và lối sống của người dân địa phương không có liên hệ đến đến tình trạng ô nhiễm môi trường.", "Các hoạt động của con người đang góp phần làm suy giảm đa dạng sinh học của Mekong."], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": "<i>Người ta vẫn lưu ý rằng tiếng gọi con người là sự kết hợp giữa hai yếu tố, đó là tiếng con - chỉ loài động vật với những phản ứng bản năng - cùng với tiếng người chỉ những đòi hỏi vươn cao. Hình ảnh nhân sư khổng lồ, dựng lên ở giữa sa mạc Ai Cập với cái đầu người và mình sư tử, hẳn là biểu tượng rõ nhất cho cuộc chiến đấu gian nan để con người được hình thành: dù đã cố ngoi đầu lên với những sắc diện là người, nhân loại vẫn còn bị lôi kéo lại bởi những thú tính thấp hèn là cái thân xác súc vật nặng nề kéo dài ở trên mặt đất. Và chỉ khi nào con người thực sự cất nổi mình lên, rũ bỏ được sự chi phối của cái thân xác bốn cẳng để đứng vững vàng trên cái tư thế hai chân, con người mới thực sự người, để tiến đến một giai đoạn cao hơn của sự thăng hoa nhân loại.</i><br><i>Cổ ngôn Đông phương: &quot;Người không mười phần hoàn toàn&quot; (nhân vô thập toàn) xác nhận sự chưa hoàn thiện của người để khích lệ người trên đường cải thiện. Chính sức cố gắng ấy là dấu hiệu riêng biệt của người, là cái vinh quang của người. Nó là món quà của lý trí, và lý trí là kết quả của sinh hoạt xã hội.</i><br><i>Suốt cuộc đời mình, Goethe đã chiến đấu không ngừng để mở rộng sự hiểu biết và câu nói cuối cùng của ông trước khi nhắm mắt: &quot;Hãy cho thêm ánh sáng&quot; đã thành châm ngôn bất hủ: hãy thêm ánh sáng cho căn phòng nhỏ bóng tối âm u, hãy thêm ánh sáng cho những tâm hồn còn ham hiểu biết, hãy thêm ánh sáng cho những kiếp sống còn muốn vươn lên. Qua câu nói khác rất được truyền tụng: &quot;Tôi là một người, nghĩa là một chiến sĩ”, Goethe đã xác định thêm rõ cái nội dung người: đó là mọi sự nỗ lực vượt qua trở ngại, một sự khao khát đi tới không ngừng để thoát khỏi những xiềng xích nô lệ và những thấp hèn.</i><br><i>Tùy theo sức chiến đấu ấy mà giá trị người mới được xác định, bởi lẽ có những chiến đấu thất bại và những chiến đấu thành công. Thể hiện được sức lớn lao của sự thành công hay nỗi xót xa của sự thất bại, ít nhiều cũng đã thể hiện được tính cách người trên nhận thức ấy. Con người đói khổ bênh vực được đồng loại mình một cách gian nan ở trong tác phẩm &quot;Những kẻ khốn nạn&quot; đã làm vẻ vang Victor Hugo, cũng như con người tu hành sa ngã thảm thương tự kết liễu mình trong tác phẩm &quot;Mưa&quot; đã đưa Somerset Maugham lên đài danh vọng.</i><br>(Trích theo Ngày xuân nói chuyện con người, Vũ Hạnh)", "cauHoi": [{"question": "Luận đề của văn bản trên là gì?", "choices": ["Con người là sự kết hợp giữa bản năng động vật và lý trí xã hội.", "Quá trình trở thành con người hoàn thiện là cuộc đấu tranh không ngừng.", "Lý trí là yếu tố quyết định duy nhất làm nên bản chất con người.", "Con người chỉ thực sự có giá trị khi đạt đến trạng thái hoàn thiện tuyệt đối."], "correctIndex": 1, "explain": ""}, {"question": "Đâu là nhận định không được triển khai trong văn bản?", "choices": ["Con người luôn tồn tại trong trạng thái chưa hoàn thiện và cần không ngừng cải thiện.", "Sự đấu tranh vượt lên bản năng là biểu hiện bản chất của con người.", "Giá trị con người được xác định thông qua kết quả thành công hay thất bại trong đấu tranh.", "Con người về bản chất luôn chiến thắng bản năng nhờ ưu thế của lý trí."], "correctIndex": 3, "explain": ""}, {"question": "Ý nghĩa của việc viện dẫn hình tượng Nhân sư Ai Cập, cổ ngôn Đông Phương và các tác phẩm của Victor Hugo, Somerset Maugham là gì?", "choices": ["Minh họa sự đối lập giữa văn hóa phương Đông và phương Tây trong quan niệm về con người.", "Minh hoạ cho cuộc đấu tranh giữa bản năng và lý trí trong quá trình hình thành con người.", "Khái quát hóa tiến trình phát triển của nhận thức nhân loại về bản chất con người qua các hình tượng văn hóa và văn học.", "Làm nổi bật vai trò của các hình tượng biểu tượng trong việc lý giải những mâu thuẫn nội tại của con người."], "correctIndex": 1, "explain": ""}, {"question": "Theo văn bản, yếu tố nào sau đây được xem là dấu hiệu riêng biệt và là “vinh quang” của con người?", "choices": ["Khả năng cảm xúc và đồng cảm với đồng loại.", "Sức mạnh thể chất giúp con người sinh tồn.", "Nỗ lực không ngừng để cải thiện bản thân.", "Khả năng sáng tạo ra các giá trị văn hóa."], "correctIndex": 2, "explain": ""}, {"question": "Thái độ của tác giả đối với con người được thể hiện rõ nhất qua nhận định nào sau đây?", "choices": ["Bi quan trước sự yếu đuối và bất toàn cố hữu của con người.", "Trung lập khi nhìn nhận con người như một thực thể vừa cao cả vừa thấp hèn.", "Lạc quan và đề cao khả năng tự vượt lên, hoàn thiện của con người.", "Phê phán mạnh mẽ những hạn chế bản năng của con người."], "correctIndex": 2, "explain": "<table class=\"bang-de\"><tr><td><b>Câu</b></td><td><b>1</b></td><td><b>2</b></td><td><b>3</b></td><td><b>4</b></td><td><b>5</b></td><td><b>6</b></td><td><b>7</b></td><td><b>8</b></td><td><b>9</b></td><td><b>10</b></td><td><b>11</b></td><td><b>12</b></td><td><b>13</b></td><td><b>14</b></td><td><b>15</b></td></tr><tr><td>ĐA</td><td>C</td><td>A</td><td>D</td><td>A</td><td>C</td><td>A</td><td>B</td><td>B</td><td>A</td><td>D</td><td>D</td><td>D</td><td>A</td><td>B</td><td>B</td></tr><tr><td><b>Câu</b></td><td><b>16</b></td><td><b>17</b></td><td><b>18</b></td><td><b>19</b></td><td><b>20</b></td><td><b>21</b></td><td><b>22</b></td><td><b>23</b></td><td><b>24</b></td><td><b>25</b></td><td><b>26</b></td><td><b>27</b></td><td><b>28</b></td><td><b>29</b></td><td><b>30</b></td></tr><tr><td>ĐA</td><td>C</td><td>B</td><td>A</td><td>B</td><td>C</td><td>B</td><td>C</td><td>C</td><td>B</td><td>C</td><td>B</td><td>D</td><td>B</td><td>C</td><td>C</td></tr></table>"}], "khongXaoTron": true}], "anh": [{"noiDungChung": null, "cauHoi": [{"question": "<i class=\"huong-dan-cau\">Mark the letter A, B, C, or D on your answer sheet to indicate the correct answer to each of the following questions.</i><br>The drugs they prescribed caused my vision to blur and my skin to break ___ in spots.", "choices": ["up", "away", "through", "out"], "correctIndex": 3, "explain": "<b>Câu 31. Chọn D</b><br><b><u>Hướng dẫn</u><i>: break out</i> = nổi lên (mụn, phát ban)</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Two weeks from now, we ___ our destination.", "choices": ["will have reached", "will be reaching", "will reach", "will have been reached"], "correctIndex": 0, "explain": "<b><u>Hướng dẫn</u><i>: Chọn A – will have reached</i></b><br><b><i>Thì Tương lai hoàn thành ($will + have + V3/ed). </i></b><br><b><i>Dấu hiệu &quot;Two weeks from now&quot; (2 tuần tính từ bây giờ) chỉ một hành động sẽ hoàn tất tại một thời điểm trong tương lai.</i></b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "If you eat three good meals a day, you&#x27;re ___ likely to snack on biscuits and crisps.", "choices": ["the most", "the least", "more", "less"], "correctIndex": 3, "explain": "<b><u>Hướng dẫn: </u><i>Chọn D – less Cấu trúc so sánh: Less likely to do something (ít có khả năng làm gì). </i></b> <b><i>Ngữ cảnh: Nếu ăn đủ 3 bữa, bạn sẽ ít có nhu cầu ăn vặt hơn.</i></b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "The more _______ and positive he looks, the better he will feel.", "choices": ["confide", "confidence", "confidently", "confident"], "correctIndex": 3, "explain": "<b><u>Hướng dẫn</u><i>: Chọn D – confident</i></b><br><b><i>Cấu trúc song hành: Sau &quot;looks&quot; (linking verb) cần tính từ. &quot;Positive&quot; là tính từ nên từ cần điền cũng là tính từ: Confident (tự tin). </i></b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "There is ___ interest in harnessing wind and waves as new sources of power.", "choices": ["a number of", "several", "a great deal of", "a few"], "correctIndex": 2, "explain": "<b><u>Hướng dẫn</u><i>: Chọn C - a great deal of</i></b><br>&quot;Interest&quot; là danh từ không đếm được. <i>A number of, several, a few</i> đi với danh từ đếm được số nhiều.<br><b>A great deal of</b> đi với danh từ không đếm được."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Working as <u>a</u> <u>restaurant’s</u> owner can be exciting since <u>it</u> lets you experiment<br>with different menus and meet a diverse group of <u>customers</u>.", "choices": ["a", "restaurant’s", "it", "customers"], "correctIndex": 1, "explain": "<b><u>Hướng dẫn</u><i>: Chọn B.</i></b><br><b><i> </i></b>Lỗi sai sở hữu cách. Ở đây &quot;restaurant owner&quot; (chủ nhà hàng) là một cụm danh từ, không cần dấu sở hữu &#x27;s ở giữa. Sửa thành: <b>restaurant</b>."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "They <u>are</u> employed <u>as</u> monitors to make sure that <u>the</u> organization works<br>within <u>a</u> law.", "choices": ["are", "as", "the", "a"], "correctIndex": 3, "explain": "<b><u>Hướng dẫn</u><i>: Chọn D.</i></b><br>Cụm từ cố định: <b>Within the law</b> (trong khuôn khổ pháp luật). Sửa &quot;a law&quot; thành &quot;<b>the law</b>&quot;."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<u>A</u> job like <u>her</u> would be much too demanding for <u>me</u>, but <u>she</u> enjoys that kind<br>of life.", "choices": ["A", "her", "me", "she"], "correctIndex": 1, "explain": "<b><u>Hướng dẫn</u><i>:</i>Chọn B. her</b><br>So sánh giữa hai đối tượng tương đương. &quot;A job&quot; (một công việc) không thể so sánh với &quot;her&quot; (cô ấy). Phải so sánh với công việc của cô ấy: <b>hers</b> (đại từ sở hữu)."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Fraud detectives <u>are</u> investigating <u>the </u>company, three of <u>whom</u> senior<br>executives have already <u>been</u> arrested.", "choices": ["are", "the", "whom", "been"], "correctIndex": 2, "explain": "<b><u>Hướng dẫn</u><i>: </i>Chọn C. whom</b><br>Lỗi đại từ quan hệ. Ở đây chỉ sự sở hữu (3 người trong số các giám đốc của công ty). Sửa &quot;whom&quot; thành <b>whose</b> (three of <b>whose</b> senior executives...)."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Either <u>the</u> teachers <u>or</u> the principal <u>have</u> donated money <u>to</u> the band each year.", "choices": ["the", "or", "have", "to"], "correctIndex": 2, "explain": "<b><u>Hướng dẫn</u><i>: </i>Câu 40 . Chọn C. have</b><br>Cấu trúc <b>Either A or B</b>: Động từ chia theo chủ ngữ gần nhất (B). &quot;The principal&quot; là số ít nên động từ phải là <b>has</b>."}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 41-45: </b>Which of the following best restates each of the given sentences?", "cauHoi": [{"question": "&quot;I will visit my grandparents next weekend,&quot; he said.", "choices": ["He said he will visit his grandparents next weekend.", "He says he would visit his grandparents the following weekend.", "He says he will visit his grandparents next weekend.", "He said he would visit his grandparents the following weekend."], "correctIndex": 3, "explain": "<b><u>Hướng dẫn</u><i>: </i>Câu 41 . Chọn D. </b><br><b>Câu tường thuật: Lùi thì <i>will -&gt; would</i>, đổi trạng ngữ <i>next weekend -&gt; the following weekend</i>.</b>"}, {"question": "The event was postponed due to the storm.", "choices": ["If it hadn’t stormed, the event wouldn’t have been postponed.", "If there is a storm, the event will be postponed.", "The event would be postponed unless there was a storm.", "If it stormed, the event would not be postponed."], "correctIndex": 0, "explain": "<b><u>Hướng dẫn</u><i>: </i>Câu 42. Chọn A</b><br>Câu điều kiện loại 3 (diễn tả sự việc trái ngược quá khứ). Sự thật là &quot;The event was postponed&quot; (quá khứ). Câu A: &quot;Nếu trời không bão, sự kiện đã không bị hoãn&quot;."}, {"question": "Increasing the number of bilingual schools improves students&#x27; language skills.", "choices": ["More bilingual schools make students’ language skills worse.", "Students’ language skills worsen as the number of bilingual schools increases.", "The fewer bilingual schools there are, the less students struggle with languages.", "The more bilingual schools there are, the better students&#x27; language skills become."], "correctIndex": 3, "explain": "<b><u>Hướng dẫn</u><i>: </i>Câu 43. Chọn D.</b><br><b>Cấu trúc so sánh càng... càng...: The more + S + V, the better + S + V.</b>"}, {"question": "Notice! Visitors are required to turn off their mobile phones inside the museum.", "choices": ["Visitors should turn off their mobile phones inside the museum.", "Visitors must turn off their mobile phones inside the museum.", "Visitors may have turned off their mobile phones inside the museum.", "Visitors should have turned off their mobile phones inside the museum."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn</u><i>: </i>Câu 44. Chọn B</b><br>&quot;Required&quot; (được yêu cầu/bắt buộc) tương đương với động từ khuyết thiếu <b>must</b> (phải)."}, {"question": "The café is quieter than usual, possibly because of the early hour.", "choices": ["The decline in customers is unlikely due to the early hour.", "It is possible that the early hour will not affect the number of customers.", "The early hour may be the reason for the quiet café.", "The decline in customers is certainly due to the early hour."], "correctIndex": 2, "explain": "<b><u>Hướng dẫn</u><i>: </i>Câu 45. Chọn C</b><br>&quot;Possibly&quot; (có khả năng) tương đương với <b>may</b> (có lẽ/có thể)."}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 46-52: Read the passage carefully and choose an option (A, B, C, or D) that best answers each question.</b><br><b>1.</b> As our world becomes more globally connected, there are incredible advantages to nurturing bilingualism in children from a young age. Bilingual children often demonstrate better critical thinking abilities, creativity, and problem-solving skills than monolinguals. As a child’s brain absorbs the patterns and rules of a new language, it builds pathways that enhance their cognitive development. The mental <b>agility</b> needed to switch between two languages strengthens their<br>executive functioning and ability to focus.<br><b>2.</b> Compared to monolingual peers, bilingual education helps students excel in core subjects like reading, maths, and science. The cognitive benefits translate across all areas of learning, as they can better concentrate, interpret information, and think analytically. As students move through school, their academic advantage stays clear.<br><b>3.</b> Juggling two languages requires concentration, attention control, and switching back and forth<br>seamlessly. These demands develop a bilingual brain’s capacity for multitasking. In a world of<br>constant digital distractions, having better multitasking skills and focus from an early age can only<br>be advantageous.<br><b>4.</b> Learning a foreign language exposes children to new cultures, perspectives, traditions, and<br>ways of life. It paves the way for greater cultural sensitivity, open-mindedness and being more<br>receptive to differences. In our increasingly interconnected world, <b>these</b> competencies are<br>invaluable for future success.<br><b>5.</b> Learning a different language pushes children out of their comfort zone to gain competencies<br>they’ll use. They learn better listening abilities, overcome shyness faster, and build confidence by<br>practicing communication skills. The analysis and problem-solving abilities developed also make<br>them more empathetic and flexible when faced with unfamiliar situations or people. Overall, the<br>social and communication competencies learned serve them well in all aspects of life.<br><b>6.</b> The cognitive demands of balancing two or more languages strengthen mental skills from an<br>early age. Bilingual children demonstrate better focus, working memory, and the ability to easily<br>switch between tasks. Facing constant decision-making about which language to use forces<br>bilingual brains to solve micro problems continuously. This mental exercise bolsters executive<br>functioning, resulting in faster problem-solving capacities than monolingual peers.<br>Choose an option (A, B, C, or D) that best answers each question.", "cauHoi": [{"question": "What is the passage mainly about?", "choices": ["The challenges of learning multiple languages at a young age.", "The impact of digital distractions on children&#x27;s learning.", "The benefits of bilingualism in children.", "How bilingualism can negatively affect academic performance."], "correctIndex": 2, "explain": "<b><u>Hướng dẫn</u><i>: </i>Câu 46. Chọn C. </b><br><b>The benefits of bilingualism in children.</b> (Đoạn văn liệt kê hàng loạt lợi ích từ tư duy đến kỹ năng xã hội)."}, {"question": "The closest meaning to the word &quot;<b>agility</b>&quot; in paragraph 1 is:", "choices": ["Flexibility", "Ignorance", "Endurance", "Hesitation."], "correctIndex": 0, "explain": "<b><u>Hướng dẫn</u><i>: </i>Câu 47. Chọn A. </b><br><b>Flexibility.</b> (Agility: sự linh hoạt, nhanh nhạy)."}, {"question": "In paragraph 2, which of the following is NOT mentioned as an academic benefit of bilingualism?", "choices": ["Excelling in subjects like reading, maths, and science", "Maintaining an academic advantage over time", "Improved concentration and analytical thinking", "Developing better artistic and musical abilities"], "correctIndex": 3, "explain": "<b><u>Hướng dẫn</u><i>: </i>Câu 48. Chọn D. </b><br><b>Developing better artistic and musical abilities. (Trong đoạn 2 chỉ nhắc đến đọc, toán, khoa học; không nhắc đến nghệ thuật/âm nhạc).</b>"}, {"question": "According to paragraph 3, how does bilingualism help with multitasking?", "choices": ["It improves language pronunciation and writing skills.", "It strengthens concentration and attention control, allowing for seamless switching between tasks.", "It limits exposure to digital distractions.", "It helps children memorize large amounts of information."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn</u><i>: </i>Câu 49. Chọn B. </b><br><b>It strengthens concentration and attention control...</b> (Thông tin ở đoạn 3: &quot;develop a bilingual brain’s capacity for multitasking&quot;)."}, {"question": "What does the word &quot;<b>these</b>&quot; refer to in paragraph 4?", "choices": ["Bilingual children", "Cultures, perspectives, traditions, and ways of life", "Cultural sensitivity, open-mindedness, and being receptive to differences", "Language learning techniques."], "correctIndex": 2, "explain": "<b><u>Hướng dẫn</u><i>: </i>Câu 50. Chọn C. </b><br><b>Cultural sensitivity, open-mindedness, and being receptive to differences.</b> (Từ &quot;these&quot; thay thế cho các danh từ chỉ phẩm chất vừa liệt kê ở câu trước đó)."}, {"question": "According to paragraph 5, how does learning a second language impact social skills?", "choices": ["It improves communication skills and builds confidence.", "It makes children more reserved and shy.", "It helps children avoid uncomfortable social situations.", "It makes them focus only on grammar and vocabulary."], "correctIndex": 0, "explain": "<b><u>Hướng dẫn</u><i>: </i>Câu 51. Chọn A. </b><br><b>It improves communication skills and builds confidence.</b> (Thông tin ở đoạn 5: &quot;build confidence by practicing communication skills&quot;)."}, {"question": "What can be inferred about bilingual children in paragraph 6?", "choices": ["They struggle with decision-making because they need to switch languages often.", "They may have a disadvantage in solving problems.", "They perform worse than monolingual children in school subjects.", "They develop stronger mental skills due to frequent cognitive challenges."], "correctIndex": 3, "explain": "<b><u>Hướng dẫn</u><i>: </i>Câu 52. Chọn D. </b><br><b>They develop stronger mental skills due to frequent cognitive challenges. (Đoạn 6 nói về việc não bộ phải giải quyết &quot;micro problems&quot; liên tục giúp tăng cường chức năng điều hành).</b>"}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 53-60</b>: <b>Read the passage carefully and Choose an option (A, B, C, or D) that best answers each question.</b><br><b>1.</b> Honey limeade is considered a “miracle” for health, as it provides multiple benefits such as<br>boosting the immune system, improving digestion, and cleansing the intestines. According to<br>Health People CN and Aboluowang, this natural drink is packed with essential nutrients that<br>contribute to overall well-being.<br><b>2.</b> Rich in vitamin C, honey limeade offers numerous health advantages. It not only helps prevent cancer and food poisoning but also reduces cholesterol levels, <b>alleviates</b> fatigue, and strengthens the immune system. Regular consumption of honey limeade can also provide relief from various health conditions, including diabetes, high blood pressure, anemia, colds, and osteoporosis. Furthermore, drinking warm honey limeade in the morning can help cleanse the stomach and intestines, promoting better digestion. In contrast, drinking it in the afternoon can help quench thirst and refresh the body, making it an ideal beverage for hot weather.<br><b>3.</b> One of the key components of honey limeade is its water-soluble vitamin C, which has powerful antioxidant properties. These antioxidants help fight free radicals, which can damage cells and accelerate aging. Additionally, vitamin C improves blood circulation, ensuring that oxygen and nutrients reach different parts of the body efficiently. As a result, consuming honey limeade regularly may help enhance memory, improve cognitive flexibility, and sharpen reaction time.<br><b>4.</b> With a high concentration of citric acid, <b>this beverage</b> also supports digestion, promotes hematopoiesis (the process of forming new blood cells), and enhances immunity. The citric acid in limeade not only helps break down food more effectively but also accelerates injury recovery, making it beneficial for people recovering from illness or physical strain.<br><b>5. </b>Limes are naturally rich in niacin and organic acids, which contribute to overall health. Additionally, their citric acid juice possesses strong antibacterial properties. Scientific experiments have shown that highly acidic lime juice can kill all bacteria in seashells within just 15 minutes. This antibacterial effect highlights the cleansing power of limeade, making it a useful drink for<br>supporting the body’s natural defenses against infections.<br><b>6. </b>By incorporating honey limeade into your daily routine, you can enjoy a refreshing and<br>nutritious beverage while reaping its many health benefits.", "cauHoi": [{"question": "The best title of the passage can be __________.", "choices": ["The Dangers of Drinking Honey Limeade", "The History of Honey and Lime", "How to Make the Perfect Honey Limeade", "The Health Benefits of Honey Limeade"], "correctIndex": 3, "explain": "<b><u>Hướng dẫn</u><i>: </i>Câu 53. Chọn D. </b><br><b>The Health Benefits of Honey Limeade.</b> (Bài viết tập trung vào các lợi ích sức khỏe của nước chanh mật ong)."}, {"question": "In paragraph 2, what can be inferred about drinking honey limeade in the morning?", "choices": ["It helps clean the digestive system.", "It is more effective in the afternoon.", "It may cause stomach pain.", "It can increase fatigue."], "correctIndex": 0, "explain": "<b><u>Hướng dẫn</u><i>: </i>Câu 54. Chọn A. It helps clean the digestive system.</b> (Đoạn 2: &quot;drinking warm honey limeade in the morning can help cleanse the stomach and intestines&quot;)."}, {"question": "The word &quot;<b>alleviates</b>&quot; in paragraph 2 can be replaced by ________.", "choices": ["Increases", "Reduces", "Strengthens", "Encourages."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn</u><i>: </i>Câu 55. Chọn B. </b><br><b>Reduces.</b> (Alleviate: làm giảm bớt, nhẹ bớt)."}, {"question": "In paragraph 3, it is NOT mentioned that honey limeade ________.", "choices": ["Contains vitamin C", "Improves blood circulation", "Improve memory", "Enhances digestion."], "correctIndex": 3, "explain": "<b><u>Hướng dẫn</u><i>: </i>Câu 56. Chọn D. </b><br><b>Enhances digestion. (Câu hỏi hỏi đoạn 3 KHÔNG nhắc đến gì. Đoạn 3 nói về Vitamin C, tuần hoàn máu, trí nhớ; còn &quot;digestion&quot; được nhắc ở đoạn 2 và 4).</b>"}, {"question": "The phrase &quot;<b>this beverage</b>&quot; in paragraph 4 refers to ________.", "choices": ["Water", "Green tea", "Honey limeade", "Lemon juice."], "correctIndex": 2, "explain": "<b><u>Hướng dẫn</u><i>: </i>Câu 57. Chọn C. Honey limeade</b>."}, {"question": "It can be inferred from paragraph 4 that honey limeade ________.", "choices": ["Can only be consumed by people with weak immune systems", "Helps the body recover from injuries faster", "Should not be consumed daily", "Increases blood sugar levels."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn</u><i>: </i>Câu 58. Chọn B. </b><br><b>Helps the body recover from injuries faster.</b> (Đoạn 4: &quot;accelerates injury recovery&quot;)."}, {"question": "In paragraph 5, the author uses the phrase &quot;<b>strong antibacterial properties</b>&quot; in order to ________.", "choices": ["Emphasize its ability to kill bacteria", "Show that honey limeade is unhealthy", "Explain why it tastes sour", "Indicate that limes are high in sugar."], "correctIndex": 0, "explain": "<b><u>Hướng dẫn</u><i>: </i>Câu 59. Chọn A. Emphasize its ability to kill bacteria.</b> (Antibacterial: kháng khuẩn)."}, {"question": "It can be seen in paragraphs 3, 4, and 5 that ________.", "choices": ["Honey limeade only benefits digestion.", "Honey limeade should not be consumed regularly.", "Honey limeade contains essential nutrients that support overall health.", "The main benefit of honey limeade is improving sleep quality."], "correctIndex": 2, "explain": "<b><u>Hướng dẫn</u><i>: </i>Câu 60. Chọn C. </b><br><b>Honey limeade contains essential nutrients that support overall health.</b> (Đây là ý tóm lược chung cho cả 3 đoạn về các chất dinh dưỡng và lợi ích của chúng)."}], "khongXaoTron": true}], "kh": [{"noiDungChung": "<b>MÔN HOÁ - Dựa vào thông tin dưới đây để trả lời các Câu từ 103 đến 105 </b><br>Nitrogen là nguyên tố dinh dưỡng quan trọng cho sinh vật, tuy nhiên hàm lượng nitrogen cao có thể gây ô nhiểm nguồn nước. Một nghiên cúu xác dịnh hàm lượng ion ammonium ( <span class=\"ct\">NH<sub>4<sup>*</sup></sub></span> ) trong nước bề mặt ở đồng bằng Sông Cửu Long và so sánh với tiêu chuẩn (nồng độ NH<sub>4</sub><sup>+</sup> &lt; 3 mg.L<sup>-1</sup>) theo nguyên tắc sau:<br>Chuẫn bị mẫu thử bằng cách pha loãng mẫu nước 10 lần.<br>Ion NH<sub>4</sub><sup>+</sup> chuyển thành indophenol qua các phản ứng sau:<br>\\[NH_{4}\\ ^{+} + ClO^{-} \\rightarrow NH_{2}Cl + H_{2}O\\ \\]<br><span class=\"ct\">NH<sub>2</sub>Cl +</span> Dẫn xuất phenol <span class=\"ct\">→</span> Indophenol (dung dịch A)<br>Cường độ màu (đậm/nhạt) của dung dịch A tỉ lệ thuận với nồng độ indophenol trong dung dịch.<br>Khi đó máy đo cường độ màu có thể tính toán được hàm lượng indophenol, từ đó tính được hàm lượng NH<sub>4</sub><sup>+</sup> trong mẫu do. Kết quả cho thấy hàm lượng ion NH<sub>4</sub><sup>+ </sup>trong mẫu thử là 1,44 mg.L<sup>-1</sup><br>Các phản ứng cần thực hiện ở điều kiện pH trong khoảng từ 4 dến 13. Thiết bị chỉ đo được mẫu nước có hàm lượng NH<sub>4</sub><sup>+ </sup>nằm trong khoảng từ 0,26 đến 10,30 mg.L<sup>-1</sup>.", "cauHoi": [{"question": "Trước khi tiến hành đo cường độ màu, để kiếm tra pH người ta nhúng giấy quỳ tím vào mẫu thử, nhận thẫy quỳ tím không đối màu. Kết luận nào sau đây là đúng?", "choices": ["pH của mẫu thử phù hợp để tiến hành đo.", "pH của mẫu thử chưa phù hợp, cần lấy mẫu thử ở vị tri khác.", "pH của mẫu thử chưa phù hợp, cần điều chỉnh bằng acid hoặc kiềm.", "Chưa thể kết luận gì vì buớc này không có ý nghĩa trong phép đo."], "correctIndex": 0, "explain": "<b>Đáp án: A.</b><br>Do giấy quỳ tím không đổi màu, tức là mẫu thử có môi trường trung tính, có pH = 7. Theo đề bài, các phản ứng thực hiện trong điều kiện pH trong khoảng từ 4 đến 13 <span class=\"ct\">⇒</span> pH của mẫu thử phù hợp để tiến hành đo."}, {"question": "Từ kết quả thí nghiệm, một số phát biểu được đưa ra như sau:<br>(a) Hàm lượng nguyên tố nitrogen cao trong nước có thể dẫn đến hiện tượng phú dưỡng, làm tăng nồng độ oxygen hoà tan trong nước và gây ô nhiễm.<br>(b) Hàm lượng nguyên tố nitrogen tồn tại ở dạng NH<sub>4</sub><sup>+</sup>mẫu nước trên là 11,2 mg.L<sup>-1</sup>.<br>(c) Kết quả chứng tỏ NH<sub>4</sub><sup>+ </sup>trong mẩu nuớc có nguồn gốc từ phân bón trên các đồng ruộng lân cận.<br>(d) Kết quả trên khẳng định được nitrogen trong nuớc không tồn tại ở dạng nitrate (NO<sub>3</sub><sup>-</sup>).<br>Phát biếu nào là đúng?", "choices": ["Chỉ (a) và (b).", "Chỉ (b).", "Chỉ (a), (c), và (d).", "Chỉ (b) và (d)."], "correctIndex": 1, "explain": "<b>Đáp án: B.</b><br>a) <b>Sai</b> vì hàm lượng nguyên tố nitrogen cao trong nước có thể dẫn đến hiện tượng phú dưỡng, làm GIẢM nồng độ oxygen hoà tan trong nước và gây ô nhiễm.<br>b) <b>Đúng </b><br>Theo giả thuyết, hàm lượng ion NH<sub>4</sub><sup>+</sup>trong mẫu thử là 1,44 mg.L<sup>-1</sup> <span class=\"ct\">⇒</span> nN = nNH<sub>4</sub><sup>+</sup> = 1,44/18 = 0,08 (mmol/L)<br><span class=\"ct\">⇒</span> hàm lượng nguyên tố nitrogen tồn tại dạng NH<sub>4</sub><sup>+</sup> = 14.0,08 = 1,12 mg.L<sup>-1</sup>.<br>c) <b>Sai</b> NH<sub>4</sub><sup>+ </sup>trong mẩu nuớc có thể có nguồn gốc từ phân bón trên các đồng ruộng lân cận hoặc các từ nguồn khác như xả thải của nhà máy.<br>d) <b>Sai</b>, kết quả trên chưa khẳng định được nitrogen trong nuớc có hay không tồn tại ở dạng nitrate (NO<sub>3</sub><sup>-</sup>)."}, {"question": "Cho các phát biểu sau:<br>(a) Mục đích của thí nghiệm là để kiểm tra hàm lương NH<sub>4</sub><sup>+ </sup>trong nuớc bề mặt có nằm ngoài tiêu chuẩn cho phép hay không.<br>(b) Hàm lượng NH<sub>4</sub><sup>+</sup>trong mẫu nước ban đầu là 1,44 mg.L<sup>-1</sup>.<br>(c) Nồng độ NH<sub>4</sub><sup>+ </sup>trong mẩu thử càng lớn thì cường độ màu của dung dịch A càng yễu.<br>(d) Việc pha loãng nhằm tránh NH<sub>4</sub><sup>+ </sup>chuyển thành ammonia (NH<sub>3</sub>) khi tiếp xúc với kiềm.<br>(e) Có thể kết luận rằng mẫu nước này không bị ô nhiễm NH<sub>4</sub><sup>+</sup><br>Có bao nhiêu phát biếu đúng trong các phát biếu trên?", "choices": ["1.", "2.", "3.", "5."], "correctIndex": 0, "explain": "<b>Đáp án: A.</b><br>a) <b>Đúng</b><br>b) <b>Sai, </b>vì mẫu thử được pha loãng 10 lần nên hàm lượng NH<sub>4</sub><sup>+</sup>trong mẫu nước ban đầu là 14,4 mg.L<sup>-1</sup>.<br>c) <b>Sai, </b>Nồng độ NH<sub>4</sub><sup>+ </sup>trong mẩu thử càng lớn thì cường độ màu của dung dịch A càng mạnh.<br>d) <b>Sai, vì </b>việc pha loãng nhằm tránh NH<sub>4</sub><sup>+</sup> cao nằm ngoài khoảng đo được của máy.<br>e) <b>Sai </b>vì mẫu nước này bị ô nhiễm do nồng độ của NH<sub>4</sub><sup>+</sup> = 14,1 mg.L<sup>-1</sup> lớn hơn (hàm lượng NH<sub>4</sub><sup>+</sup> &lt; 3 mg.L<sup>-1</sup>)<br>"}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN LÝ - Dựa vào thông tin dưới đây để trả lời các Câu từ 106 đến 108 </b><br>Trong bối cảnh nhu cầu năng lượng toàn cầu ngày càng tăng, điện hạt nhân được xem là một giải pháp thay thế quan trọng cho nhiên liệu hóa thạch. Nguồn năng lượng này được tạo ra từ phản ứng phân hạch hạt nhân, khi các hạt nhân nặng như Uranium-235 hấp thụ neutron và bị tách thành các hạt nhỏ hơn, đồng thời giải phóng một lượng nhiệt rất lớn và các neutron mới, duy trì phản ứng dây chuyền.<br>Để phản ứng diễn ra hiệu quả, các neutron được làm chậm nhờ chất làm chậm như nước hoặc than chì, giúp tăng xác suất gây phân hạch. Đồng thời, các thanh điều khiển làm từ cadimi hoặc bo được sử dụng để hấp thụ bớt neutron, qua đó điều chỉnh tốc độ phản ứng và đảm bảo lò hoạt động ổn định, an toàn.<br>Nhiệt lượng sinh ra được dùng để đun sôi nước, tạo hơi nước áp suất cao làm quay tuabin nối với máy phát điện, biến cơ năng thành điện năng. Sau khi qua tuabin, hơi nước được làm nguội trong bộ ngưng tụ và quay trở lại chu trình, giúp hệ thống vận hành liên tục (như sơ đồ hình bên).<br>Một nhà máy điện hạt nhân có công suất điện <span class=\"ct\">P<sub>e</sub> = 1000 MW</span> với hiệu suất chuyển đổi <span class=\"ct\">η = 30%</span>. Mỗi phản ứng phân hạch của <span class=\"ct\"><sup>235</sup>U</span> giải phóng năng lượng <span class=\"ct\">E<sub>f</sub> = 200 MeV = 3,2 × 10<sup>−11</sup> J</span>. Với khối lượng mol <span class=\"ct\">235 g/mol</span> và số Avogadro <span class=\"ct\">N<sub>A</sub> = 6,02 × 10<sup>23</sup></span>, Nhờ khả năng phát điện ổn định, phát thải khí nhà kính thấp và mật độ năng lượng cao, điện hạt nhân đóng vai trò quan trọng trong việc giảm thiểu biến đổi khí hậu và đảm bảo an ninh năng lượng.", "cauHoi": [{"question": "Xét các mệnh đề sau:<br><b>(I).</b> Nguồn năng lượng trong nhà máy điện hạt nhân là phản ứng phân hạch<br><b>(II).</b> Khi <span class=\"ct\"><sup>235</sup>U</span> bị nung nóng, phản ứng phân hạch xảy ra.<br><b>(III).</b> Vai trò của neutron trong phản ứng dây chuyền là duy trì phản ứng phân hạch<br><b>(IV).</b> Chất làm chậm neutron có tác dụng tăng năng lượng neutron<br><b>(V).</b> Thanh điều khiển (Cd, Bo) có chức năng tạo neutron<br><b>(VI).</b> Nếu không kiểm soát neutron, phản ứng sẽ dừng lại<br>Trong số các ý trên, có bao nhiêu ý đúng", "choices": ["2", "3", "4", "5"], "correctIndex": 0, "explain": "<b>Đáp án A</b><br>(I) <b>Đúng</b> – Nhà máy điện hạt nhân dùng phản ứng phân hạch.<br>(II) <b>Sai</b> – Phân hạch xảy ra khi <span class=\"ct\"><sup>235</sup>U</span> <b>hấp thụ neutron</b>, không phải chỉ do nung nóng.<br>(III) <b>Đúng</b> – Neutron duy trì phản ứng dây chuyền.<br>(IV) <b>Sai</b> – Chất làm chậm có tác dụng <b>giảm năng lượng neutron</b>, không phải tăng.<br>(V) <b>Sai</b> – Thanh điều khiển <b>hấp thụ neutron</b>, không tạo neutron.<br>(VI) <b>Sai</b> – Nếu không kiểm soát, phản ứng sẽ <b>mất kiểm soát</b>, không dừng lại.<br>Có <b>2 ý đúng</b>: (I), (III)"}, {"question": "<b>Công suất nhiệt của lò xấp xỉ </b>", "choices": ["<span class=\"ct\">3,0 × 10<sup>9</sup></span> W", "<span class=\"ct\">3,33 × 10<sup>9</sup></span> W", "<span class=\"ct\">1,0 × 10<sup>9</sup></span> W", "<span class=\"ct\">0,3 × 10<sup>9</sup></span> W"], "correctIndex": 1, "explain": "<b>Giải: </b>\\(P_t=\\dfrac{P_e}{\\eta}=\\dfrac{10^9}{0{,}3}=3{,}33\\times10^9\\ \\text{W}\\)→ <b>Đáp án: B</b>"}, {"question": "Khối lượng <span class=\"ct\"><sup>235</sup>U</span> tiêu thụ trong 1 năm xấp xỉ", "choices": ["1,3 tấn", "13 tấn", "13 kg", "130 kg"], "correctIndex": 0, "explain": "<b>Chọn A</b>. <span class=\"ct\">E = P<sub>t</sub>t = 3,33 × 10<sup>9</sup>·3,15 × 10<sup>7</sup> ≈ 1,05 × 10<sup>17</sup></span>(J)<br>\\(N = \\dfrac{E}{E_f} = \\dfrac{1{,}05\\times10^{17}}{3{,}2\\times10^{-11}} \\approx 3{,}28\\times10^{27}\\)<br>\\(m = \\dfrac{N}{N_A}\\cdot235 \\approx \\dfrac{3{,}28\\times10^{27}}{6{,}02\\times10^{23}}\\cdot235 \\approx 1{,}28\\times10^3\\ \\text{kg}\\)<span class=\"ct\">→</span><b> </b><span class=\"ct\">m ≈ 1,28 × 10<sup>3</sup> kg</span>"}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN SINH - Dựa vào thông tin dưới đây để trả lời các Câu từ 109 đến 111</b><br><img class=\"anh-de\" src=\"data/anh/l9/36c297898b3d9676.jpg\" alt=\"\" style=\"width:373px;height:200px\">Thực vật tích lũy tinh bột, động vật tích lũy glycogen dưới dạng polysaccharide dự trữ. Tinh bột có 2 dạng chính, các polymer glucose không tan trong nước gọi là amylose và amylopectin. Amylose về cơ bản là dạng sợi thẳng không phân nhánh, còn amylopectin thì phân nhánh nhiều và đều đặn theo dạng phân nhánh cụm. Glycogen cũng là polymer glucose phân nhánh, nhưng không giống với amylopectin. Glycogen tương đối nhỏ hơn và tan trong nước. Ở phân tử glycogen, nhánh ngắn, không đều và không thành cụm.<i> </i>", "cauHoi": [{"question": "Sinh tổng hợp tinh bột có sự tham gia của 3 loại enzyme: kéo dài chuỗi, enzyme phân nhánh và enzyme khử nhánh bên. Sugary, là thể đột biến ở lúa, thiếu enzyme khử nhánh bên. Nội nhũ của thể đột biến này có đặc trưng là sự tích lũy của polysaccharide giống glycogen hơn thay vì amylopectin.<br>Dựa trên các thông tin này, vai trò của enzyme khử nhánh bên trong quá trình sinh tổng hợp tinh bột là:", "choices": ["Để cắt ngắn các nhánh của amylopectin.", "Để điều chỉnh kiểu phân nhánh của amylopectin.", "Để loại bỏ tất cả các nhánh từ amylopectin để tạo thành amylose.", "Để cắt liên kết mạch chính của amylopectin."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn giải</u></b><br>Amylopectin phân nhánh nhiều, dài và đều đặn còn glycogen phân nhánh không đều và ngắn. Khi thiếu đi enzyme khử nhánh bên, polysaccharide giống với glycogen hơn thay vì amylopectin, điều này chứng tỏ thể đột biến này đã làm mất đi khả năng điều chỉnh sự phân nhánh của mạch bên, khiến chuỗi polysaccharide phân nhánh hỗn loạn, không đều nhau làm chuỗi polysaccharide vừa tổng hợp có hình dạng giống glycogen hơn."}, {"question": "Các hạt của thể đột biến Sugary ở lúa không có sự khác biệt với các hạt của lúa bình thường (kiểu đại) về kích thước và hình dạng hạt trước khi hạt khô (mất nước), quá trình mất nước này có liên quan với sự chín của hạt. Tuy nhiên, trong quá trình khô của hạt, hạt Sugary bị co lại và nhăn nheo.<br>Hiện tượng này chứng tỏ rằng trước khi hạt khô, so với hạt bình thường, hạt Sugary có chứa:", "choices": ["Ít polysaccharide dự trữ, ít nước.", "Nhiều polysaccharide dự trữ, nhiều nước.", "Nhiều polysaccharide dự trữ, ít nước.", "Ít polysaccharide dự trữ, nhiều nước."], "correctIndex": 3, "explain": "<b><u>Hướng dẫn giải</u></b><br>Khi khô hạt bị co lại và nhăn nheo, chứng tỏ hàm lượng chất thô ít và hàm lượng nước nhiều, nên khi khô hạt mất phần lớn nước và chỉ còn lại hàm lượng lớn chất thô (cụ thể là polysaccharide) làm thể tích hạt giảm mạnh, trong khi diện tích bao phủ vỏ hạt vẫn không đổi, chính điều này làm cho hạt trở nên nhăn nheo."}, {"question": "Vi khuẩn Cyanobacteria tích trữ polysaccharide kiểu glycogen nhằm dự trữ glucose. Đáp án nào dưới đây có thể giải thích một cách hợp lý nhất sự tiến hóa về cách dự trữ các polysaccharide về tổ tiên chung của thực vật và động vật?", "choices": ["Có khả năng tổng hợp cả amylopectin và glycogen, nhưng thực vật mất khả năng tổng hợp glycogen trong quá trình tiến hóa.", "Có khả năng tổng hợp cả amylopectin và glycogen, nhưng động vật mất khả năng tổng hợp amylopectin.", "Có khả năng tổng hợp amylopectin nhưng không tổng hợp glycogen và động vật mới có khả năng tổng hợp glycogen.", "Có khả năng tổng hợp glycogen nhưng không tổng hợp được amylopectin, và thực vật có được khả năng tổng hợp amylopectin"], "correctIndex": 3, "explain": "<b><u>Hướng dẫn giải</u></b><br>Ở câu 1 có thể thấy nếu thiếu đi enzyme khử nhánh bên có thể làm cho polysaccharide giống hình dạng của glycogen. Chứng tỏ polysaccharide có nguồn gốc đầu tiên từ amylose kế đến là glycogen, sau quá trình tiến hóa, do thực vật có khả năng tổng hợp enzyme khử nhánh bên giúp điều chỉnh sự phân nhánh đồng đều hơn, khiến cho polysaccharide được tổng hợp trở thành amylopectin."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN ĐỊA - Dựa vào thông tin dưới đây để trả lời các Câu từ 112 đến 114 </b><br>Đồng bằng sông Cửu Long (ĐBSCL) là vựa lúa lớn nhất của Việt Nam, giúp Việt Nam trở thành một trong những quốc gia xuất khẩu gạo đứng thứ hai trên thế giới. Nếu như nơi đây có nguy cơ rủi ro tiềm ẩn từ vấn đề xâm nhập mặn, hạn hán, lũ lụt và suy giảm bùn cát cũng như xói lở bờ biển thì sự đe dọa đến nền an ninh lương thực, an ninh nguồn nước và sinh kế cho gần 21 triệu dân ở ĐBSCL. Đây là một trong những vấn đề rất nan giải.<br>Bằng chứng là nền của toàn bộ ĐBSCL những năm trở lại đây đều bị sụt lún do khai thác nước ngầm quá mức. Cùng với đó là tình trạng biến đổi khí hậu và nước biển dâng cao khoảng 0,35 cm/năm khiến nơi này bị ngập lụt là điều không thể tránh khỏi. Do vậy, việc ĐBSCL ngày một bị nhấn chìm được dự đoán là một thực tế đang từng ngày biểu hiện.<br>Vấn đề kế tiếp là tình trạng xâm nhập mặn rất phức tạp. Theo Viện Nhiệt đới môi trường (Viện Khoa học và Công nghệ quân sự), tại ĐBSCL những năm gần đây, việc xây dựng các đập thủy lợi, thủy điện của các quốc gia thượng nguồn sông Mê Kông đã làm giảm lưu lượng chảy của sông Tiền, sông Hậu vào Việt Nam, dẫn đến tình trạng xâm nhập mặn tại một số tỉnh ven biển ĐBSCL diễn ra ngày càng khắc nghiệt, phức tạp, khó lường và đặc biệt không tuân theo quy luật tự nhiên. Các sông chính và kênh nhánh bị nhiễm mặn sớm hơn, ranh giới nhiễm mặn vào sâu hơn trong nội đồng. Điều này đã gây ảnh hưởng nghiêm trọng đến đời sống và sản xuất, công trình xây dựng của ĐBSCL.<br><i>(Nguồn: Tạp chí Môi trường và Cuộc sống, Tác động của biến đổi khí hậu đối với vùng Đồng bằng sông Cửu Long) </i>", "cauHoi": [{"question": "Nền của toàn bộ ĐBSCL những năm trở lại đây đều bị sụt lún do", "choices": ["hiện tượng xói lở bờ biển.", "hiện tượng suy giảm bùn cát.", "khai thác nước ngầm quá mức.", "tình trạng xâm nhập mặn phức tạp."], "correctIndex": 2, "explain": "<b><u>Hướng dẫn giải</u></b><br><b>Đáp án: C </b><br><b>Giải thích: </b>“Bằng chứng là nền của toàn bộ ĐBSCL những năm trở lại đây đều bị sụt lún do khai thác nước ngầm quá mức”"}, {"question": "Nguyên nhân nào sau đây làm cho tình trạng xâm nhập mặn tại một số tỉnh ven biển ĐBSCL diễn ra ngày càng khắc nghiệt, phức tạp, khó lường?", "choices": ["Việc xây dựng các đập thủy điện của các nước thượng nguồn sông Mê Kông.", "Các sông chính và kênh nhánh bị nhiễm mặn sớm hơn, ranh giới nhiễm mặn vào sâu.", "Tình trạng biến đổi khí hậu và nước biển dâng cao ở nhiều địa điểm Đồng bằng sông Cửu Long.", "Tình trạng sạt lở bờ biển đang diễn ra nghiêm trọng dọc theo bờ biển Đồng bằng sông Cửu Long."], "correctIndex": 0, "explain": "<b><u>Hướng dẫn giải</u></b><br><b>Đáp án: A </b><br><b>Giải thích: </b>“tại ĐBSCL những năm gần đây, <b><i>việc xây dựng các đập thủy lợi, thủy điện của các quốc gia thượng nguồn sông Mê Kông </i></b>đã làm giảm lưu lượng chảy của sông Tiền, sông Hậu vào Việt Nam, dẫn đến tình trạng xâm nhập mặn tại một số tỉnh ven biển ĐBSCL diễn ra ngày càng khắc nghiệt, phức tạp, khó lường”"}, {"question": "Vấn đề nào sau đây <b>không </b>được đề cập tới trong đoạn trích trên?", "choices": ["Đồng bằng sông Cửu Long là vựa lúa lớn nhất của Việt Nam.", "Biến đổi khí hậu khiến cho Đồng bằng sông Cửu Long ngập lụt.", "Tình trạng xâm nhập mặn ở Đồng bằng sông Cửu Long phức tạp.", "Xói lở bờ biển Đồng bằng sông Cửu Long làm mất nhà cửa người dân."], "correctIndex": 3, "explain": "<b><u>Hướng dẫn giải</u></b><br><b>Đáp án: D </b><br><b>A,B,C đều được đề cập trong đoạn trích: </b><br><b>A. </b>“Đồng bằng sông Cửu Long (ĐBSCL) là vựa lúa lớn nhất của Việt Nam”<br><b>B. </b>“Cùng với đó là tình trạng biến đổi khí hậu và nước biển dâng cao khoảng 0,35 cm/năm khiến nơi này bị ngập lụt là điều không thể tránh khỏi”<br><b>C. </b>“Vấn đề kế tiếp là tình trạng xâm nhập mặn rất phức tạp”<br><b>D. </b>“Xói lở bờ biển Đồng bằng sông Cửu Long làm mất nhà cửa người dân” không được đề cập tới trong đoạn trích."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN SỬ - Dựa vào thông tin dưới đây để trả lời các Câu từ 115 đến 117</b><br>Sau khi Chiến tranh lạnh kết thúc, thế giới đã chứng kiến sự tan rã của trật tự hai cực do Mỹ và Liên Xô đứng đầu. Sau khi Liên Xô sụp đổ, Mỹ có được lợi thế tạm thời trong việc thiết lập trật tự đơn cực do Mỹ hoàn toàn chi phối nhưng cũng phải đối mặt với nhiều thách thức nội tại và quốc tế. Nhiều quốc gia khác như Trung Quốc, Nga, Ấn Độ, và các nước thuộc Liên minh châu Âu (EU) tăng cường sức mạnh về kinh tế, chính trị và quân sự. Sự gia tăng sức mạnh và tầm ảnh hưởng của các quốc gia này đã góp phần tạo nên một thế giới đa cực.", "cauHoi": [{"question": "Sau Chiến tranh lạnh, thế giới phát triển theo xu thế nào sau đây?", "choices": ["Xu thế đơn cực.", "Lấy phát triển quân sự làm trung tâm.", "Xu thế đa cực.", "Lấy phát triển giáo dục làm trọng tâm."], "correctIndex": 2, "explain": "<i class=\"canh-bao-lg\">(Lưu ý: lời giải gốc ghi đáp án B, còn đáp án tô trong đề là C — web đang dùng C.)</i><br><b><u>Hướng dẫn giải</u></b><br>Sau Chiến tranh lạnh, thế giới phát triển theo xu thế đa cực nhiều trung tâm.<br>Đáp án B, D sai vì các nước lấy phát triển kinh tế làm trung tâm.<br><b>Chọn C. </b>"}, {"question": "Nội dung nào sau đây phản ánh đúng tình hình thế giới sau khi Chiến tranh lạnh (1947 – 1989) kết thúc?", "choices": ["Mỹ thực hiện thành công âm mưu bá chủ số một, duy nhất của thế giới.", "Các mâu thuẫn được giải quyết triệt để, thế giới không còn những xung đột.", "Hệ thống xã hội chủ nghĩa tiếp tục có bước phát triển mạnh mẽ trên toàn cầu.", "Sự phát triển mạnh mẽ của thương mại quốc tế với xu thế toàn cầu hóa."], "correctIndex": 3, "explain": "<i class=\"canh-bao-lg\">(Lưu ý: lời giải gốc ghi đáp án A, còn đáp án tô trong đề là D — web đang dùng D.)</i><br><b><u>Hướng dẫn giải</u></b><br><b>Đáp án A: </b>sai vì Mỹ chưa thể thực hiện thành công âm mưu bá chủ số một, duy nhất của thế giới vì giữa khả năng hiện tại và tham vọng to lớn của Mỹ còn là một khoảng cách không nhỏ.<br><b>Đáp án B: </b>sai vì hiện nay các mâu thuẫn và xung đột trên thế giới vẫn còn tồn tại.<br><b>Đáp án C: </b>sai vì sự sụp đổ của Liên Xô và các nước Đông Âu đã đánh dấu sự sụp đổ của hệ thống XHCN<b>. </b><br><b>Chọn D. </b>"}, {"question": "Chiến tranh lạnh (1947 - 1989) kết thúc đã làm cho", "choices": ["kinh tế trở thành nội dung căn bản trong quan hệ quốc tế.", "quan hệ giữa các nước lớn diễn ra theo chiều hướng đối đầu.", "chạy đua vũ trang trở thành hình thức cạnh tranh chủ yếu giữa các nước.", "sức mạnh của các quốc gia không phụ thuộc vào lực lượng quốc phòng."], "correctIndex": 0, "explain": "<i class=\"canh-bao-lg\">(Lưu ý: lời giải gốc ghi đáp án B, còn đáp án tô trong đề là A — web đang dùng A.)</i><br><b><u>Hướng dẫn giải</u></b><br><b>Đáp án B: </b>sai vì sau 1991, các nước lớn điều chỉnh chính sách theo hướng đối thoại và thỏa hiệp.<br><b>Đáp án C: </b>sai vì sau 1991, cạnh tranh kinh tế trở thành hình thức cạnh tranh chủ yếu giữa các nước.<br><b>Đáp án D: </b>sai vì mặc dù sức mạnh của quốc gia dựa trên kinh tế là chủ yếu nhưng quốc phòng vẫn giữ 1 vai trò không nhỏ.<br><b>Chọn A.</b>"}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN KTPL - Dựa vào thông tin dưới đây để trả lời các Câu từ 118 đến 120 </b><br>Dân chủ trực tiếp và dân chủ đại diện là hai hình thức cơ bản để thực hiện quyền lực của nhân dân, đều có vai trò quan trọng trong nền dân chủ. Điều 6 Hiến pháp 2013 ghi: &quot;Nhân dân thực hiện quyền lực nhà nước bằng dân chủ trực tiếp, bằng dân chủ đại diện thông qua Quốc hội, Hội đồng nhân dân và thông qua các cơ quan khác của Nhà nước&quot;. Dân chủ trực tiếp là việc nhân dân trực tiếp thực hiện quyền lực nhà nước. Hình thức biểu hiện cụ thể của dân chủ trực tiếp chủ yếu thông qua 3 hình thức sau: ứng cử, bầu cử, bãi nhiệm đại biểu Quốc hội, Hội đồng nhân dân; thực hiện quy chế dân chủ cơ sở; trưng cầu dân ý. Ngoài ra, các cuộc đối thoại trực tiếp của nhân dân với cơ quan Nhà nước hiện nay cũng là hình thức biểu hiện của dân chủ trực tiếp. Dân chủ đại diện là hình thức thực hiện quyền làm chủ của người dân thông qua bộ máy nhà nước, các cơ quan nhà nước, mà trước hết và quan trọng là các cơ quan đại diện do dân cử và các tổ chức chính trị xã hội.", "cauHoi": [{"question": "Dân chủ đại diện còn có tên gọi khác là gì?", "choices": ["Dân chủ không hoàn toàn", "Dân chủ không đầy đủ", "Dân chủ gián tiếp", "Dân chủ không công khai."], "correctIndex": 2, "explain": "<b><u>Hướng dẫn giải</u></b><br><b>Đáp án: C. </b>"}, {"question": "Theo đoạn trích, việc thực hiện quyền lực nhà nước thông qua bầu cử là hình thức dân chủ nào?", "choices": ["Dân chủ trực tiếp", "Dân chủ đại diện", "Dân chủ phân quyền", "Không phải một hình thức dân chủ."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn giải</u></b><br><b>Đáp án: B.</b>"}, {"question": "Dựa vào Điều 6 Hiến pháp 2013 và những thông tin từ đoạn trích, hình thức nào dưới đây KHÔNG phải là biểu hiện của dân chủ trực tiếp?", "choices": ["Ứng cử vào Quốc hội.", "Bầu cử đại biểu Hội đồng nhân dân.", "Thực hiện quy chế dân chủ cơ sở.", "Thực hiện các nghị quyết của Quốc hội."], "correctIndex": 3, "explain": "<b><u>Hướng dẫn giải</u></b><br><b>Đáp án : D</b>"}], "khongXaoTron": true}]};
